{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE snitch_db.maplemonk.perfumes_retention_overall_sku_level AS WITH orders_union AS ( SELECT \'+91\' || RIGHT( REGEXP_REPLACE(phone, \'[^0-9]\', \'\'), 10 ) AS phone_no, order_timestamp::DATE AS order_date, UPPER(sku_group) AS order_sku_group, SUM(gross_sales) AS sales, SUM(quantity) AS quantity, COUNT(DISTINCT combined_order_name) AS orders, \'Online\' AS order_store FROM snitch_db.maplemonk.fact_items_snitch WHERE UPPER(sku_group) LIKE \'%4MSFR%\' AND order_timestamp::DATE >= \'2024-01-01\' GROUP BY 1,2,3 UNION ALL SELECT \'+91\' || RIGHT( REGEXP_REPLACE(phone, \'[^0-9]\', \'\'), 10 ) AS phone_no, order_timestamp::DATE AS order_date, UPPER(sku_group) AS order_sku_group, SUM(selling_price) AS sales, SUM(suborder_quantity) AS quantity, COUNT(DISTINCT order_name) AS orders, \'Offline\' AS order_store FROM snitch_db.maplemonk.store_fact_items_offline WHERE LOWER(marketplace_mapped) NOT LIKE \'%wh%\' AND UPPER(sku_group) LIKE \'%4MSFR%\' AND order_timestamp::DATE >= \'2024-01-01\' GROUP BY 1,2,3 ), orders_clean AS ( SELECT phone_no, order_date, order_store, order_sku_group, SUM(sales) AS sales, SUM(quantity) AS quantity, SUM(orders) AS orders FROM orders_union WHERE LENGTH(phone_no) = 13 AND phone_no NOT IN ( \'+911234567890\', \'+911234567891\', \'+910123456789\', \'+911111111111\', \'+912727272727\', \'+918888888888\', \'+919999999999\', \'+910000000000\', \'+912424242424\', \'+919909090909\' ) GROUP BY 1,2,3,4 ), cohorts AS ( SELECT phone_no, sku_group AS acq_sku_group, first_order_date, DATE_TRUNC( \'month\', first_order_date ) AS acq_month, acq_channel AS acq_store FROM snitch_db.maplemonk.customer_acq_date_channel_sku WHERE first_order_date >= \'2024-01-01\' ), orders_with_month_diff AS ( SELECT c.phone_no, c.first_order_date, c.acq_month, c.acq_store, c.acq_sku_group, o.order_date, o.order_store, o.order_sku_group, o.sales, o.quantity, o.orders, DATEDIFF( \'month\', c.first_order_date, o.order_date ) AS month_diff FROM cohorts c INNER JOIN orders_clean o ON c.phone_no = o.phone_no AND o.order_date >= c.first_order_date ), views AS ( SELECT \'overall_any_acq_any_repeat\' AS view_type, NULL::VARCHAR AS acq_store_filter, NULL::VARCHAR AS repeat_store_filter UNION ALL SELECT \'online_acq_overall\', \'Online\', NULL UNION ALL SELECT \'offline_acq_overall\', \'Offline\', NULL UNION ALL SELECT \'online_acq_online\', \'Online\', \'Online\' UNION ALL SELECT \'online_acq_offline\', \'Online\', \'Offline\' UNION ALL SELECT \'offline_acq_offline\', \'Offline\', \'Offline\' UNION ALL SELECT \'offline_acq_online\', \'Offline\', \'Online\' ), metrics AS ( SELECT v.view_type, o.acq_month, o.acq_sku_group AS sku_group, COUNT( DISTINCT o.phone_no ) AS acq_customers, SUM( CASE WHEN o.month_diff = 0 AND o.order_sku_group = o.acq_sku_group THEN o.sales ELSE 0 END ) AS acq_sales, SUM( CASE WHEN o.month_diff = 0 AND o.order_sku_group = o.acq_sku_group THEN o.quantity ELSE 0 END ) AS acq_quantity, COUNT( DISTINCT CASE WHEN o.month_diff = 1 AND ( v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter ) THEN o.phone_no END ) AS m1_customers, SUM( CASE WHEN o.month_diff = 1 AND ( v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter ) THEN o.sales ELSE 0 END ) AS m1_sales, SUM( CASE WHEN o.month_diff = 1 AND ( v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter ) THEN o.quantity ELSE 0 END ) AS m1_quantity, COUNT( DISTINCT CASE WHEN o.month_diff BETWEEN 1 AND 3 AND ( v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter ) THEN o.phone_no END ) AS m3_customers, SUM( CASE WHEN o.month_diff BETWEEN 1 AND 3 AND ( v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter ) THEN o.sales ELSE 0 END ) AS m3_sales, SUM( CASE WHEN o.month_diff BETWEEN 1 AND 3 AND ( v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter ) THEN o.quantity ELSE 0 END ) AS m3_quantity, COUNT( DISTINCT CASE WHEN o.month_diff BETWEEN 1 AND 6 AND ( v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter ) THEN o.phone_no END ) AS m6_customers, SUM( CASE WHEN o.month_diff BETWEEN 1 AND 6 AND ( v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter ) THEN o.sales ELSE 0 END ) AS m6_sales, SUM( CASE WHEN o.month_diff BETWEEN 1 AND 6 AND ( v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter ) THEN o.quantity ELSE 0 END ) AS m6_quantity, COUNT( DISTINCT CASE WHEN o.month_diff BETWEEN 1 AND 12 AND ( v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter ) THEN o.phone_no END ) AS m12_customers, SUM( CASE WHEN o.month_diff BETWEEN 1 AND 12 AND ( v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter ) THEN o.sales ELSE 0 END ) AS m12_sales, SUM( CASE WHEN o.month_diff BETWEEN 1 AND 12 AND ( v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter ) THEN o.quantity ELSE 0 END ) AS m12_quantity, COUNT( DISTINCT CASE WHEN o.month_diff BETWEEN 1 AND 18 AND ( v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter ) THEN o.phone_no END ) AS m18_customers, SUM( CASE WHEN o.month_diff BETWEEN 1 AND 18 AND ( v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter ) THEN o.sales ELSE 0 END ) AS m18_sales, SUM( CASE WHEN o.month_diff BETWEEN 1 AND 18 AND ( v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter ) THEN o.quantity ELSE 0 END ) AS m18_quantity, COUNT( DISTINCT CASE WHEN o.month_diff BETWEEN 1 AND 24 AND ( v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter ) THEN o.phone_no END ) AS m24_customers, SUM( CASE WHEN o.month_diff BETWEEN 1 AND 24 AND ( v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter ) THEN o.sales ELSE 0 END ) AS m24_sales, SUM( CASE WHEN o.month_diff BETWEEN 1 AND 24 AND ( v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter ) THEN o.quantity ELSE 0 END ) AS m24_quantity FROM views v INNER JOIN orders_with_month_diff o ON ( v.acq_store_filter IS NULL OR o.acq_store = v.acq_store_filter ) GROUP BY 1,2,3 ) SELECT view_type, acq_month, sku_group, acq_customers, acq_sales::INT AS acq_sales, acq_quantity::INT AS acq_quantity, m1_customers, m3_customers, m6_customers, m12_customers, m18_customers, m24_customers, DIV0( m1_customers, acq_customers ) AS m1_customer_retention, DIV0( m3_customers, acq_customers ) AS m3_customer_retention, DIV0( m6_customers, acq_customers ) AS m6_customer_retention, DIV0( m12_customers, acq_customers ) AS m12_customer_retention, DIV0( m18_customers, acq_customers ) AS m18_customer_retention, DIV0( m24_customers, acq_customers ) AS m24_customer_retention, DIV0( m1_sales, acq_sales ) AS m1_sales_retention, DIV0( m3_sales, acq_sales ) AS m3_sales_retention, DIV0( m6_sales, acq_sales ) AS m6_sales_retention, DIV0( m12_sales, acq_sales ) AS m12_sales_retention, DIV0( m18_sales, acq_sales ) AS m18_sales_retention, DIV0( m24_sales, acq_sales ) AS m24_sales_retention, DIV0( m1_quantity, acq_quantity ) AS m1_quantity_retention, DIV0( m3_quantity, acq_quantity ) AS m3_quantity_retention, DIV0( m6_quantity, acq_quantity ) AS m6_quantity_retention, DIV0( m12_quantity, acq_quantity ) AS m12_quantity_retention, DIV0( m18_quantity, acq_quantity ) AS m18_quantity_retention, DIV0( m24_quantity, acq_quantity ) AS m24_quantity_retention FROM metrics ORDER BY view_type, acq_month, sku_group ; CREATE OR REPLACE TABLE snitch_db.maplemonk.perfume_retention_datatable AS WITH all_order_items AS ( SELECT \'+91\' || RIGHT(REGEXP_REPLACE(phone, \'[^0-9]\', \'\'), 10) AS phone_no, combined_order_name::STRING AS order_id, order_timestamp, order_timestamp::DATE AS order_date, \'Online\' AS channel, UPPER(sku_group) AS sku_group, gross_sales AS sales, quantity, CASE WHEN UPPER(sku_group) LIKE \'%4MSFR%\' THEN 1 ELSE 0 END AS is_perfume, CASE WHEN UPPER(sku_group) NOT LIKE \'%4MSFR%\' OR sku_group IS NULL THEN 1 ELSE 0 END AS is_other FROM snitch_db.maplemonk.fact_items_snitch UNION ALL SELECT \'+91\' || RIGHT(REGEXP_REPLACE(phone, \'[^0-9]\', \'\'), 10) AS phone_no, order_name::STRING AS order_id, order_timestamp, order_timestamp::DATE AS order_date, \'Offline\' AS channel, UPPER(sku_group) AS sku_group, selling_price AS sales, suborder_quantity AS quantity, CASE WHEN UPPER(sku_group) LIKE \'%4MSFR%\' THEN 1 ELSE 0 END AS is_perfume, CASE WHEN UPPER(sku_group) NOT LIKE \'%4MSFR%\' OR sku_group IS NULL THEN 1 ELSE 0 END AS is_other FROM snitch_db.maplemonk.store_fact_items_offline WHERE LOWER(marketplace_mapped) NOT LIKE \'%wh%\' ), clean_items AS ( SELECT * FROM all_order_items WHERE LENGTH(phone_no) = 13 AND phone_no NOT IN ( \'+911234567890\', \'+911234567891\', \'+910123456789\', \'+911111111111\', \'+912727272727\', \'+918888888888\', \'+919999999999\', \'+910000000000\', \'+912424242424\', \'+919909090909\' ) ), order_level AS ( SELECT phone_no, channel, order_id, order_timestamp, order_date, channel || \'|\' || order_id AS order_key, SUM(sales) AS order_sales, SUM(quantity) AS order_quantity, SUM( CASE WHEN is_perfume = 1 THEN sales ELSE 0 END ) AS perfume_sales, SUM( CASE WHEN is_other = 1 THEN sales ELSE 0 END ) AS other_sales, SUM( CASE WHEN is_perfume = 1 THEN quantity ELSE 0 END ) AS perfume_quantity, MAX(is_perfume) AS has_perfume, MAX(is_other) AS has_other FROM clean_items GROUP BY 1,2,3,4,5 ), company_acq AS ( SELECT phone_no, order_key AS company_acq_order_key, order_date AS company_acq_date, order_timestamp AS company_acq_timestamp, channel AS company_acq_channel, order_sales AS company_acq_order_sales, has_perfume AS company_acq_has_perfume, has_other AS company_acq_has_other FROM order_level QUALIFY ROW_NUMBER() OVER ( PARTITION BY phone_no ORDER BY order_timestamp, order_key ) = 1 ), perfume_acq AS ( SELECT phone_no, order_key AS perfume_acq_order_key, order_date AS perfume_acq_date, order_timestamp AS perfume_acq_timestamp, channel AS perfume_acq_channel, order_sales AS perfume_acq_order_sales, perfume_sales AS perfume_acq_perfume_sales, perfume_quantity AS perfume_acq_quantity, has_other AS perfume_acq_has_other FROM order_level WHERE has_perfume = 1 QUALIFY ROW_NUMBER() OVER ( PARTITION BY phone_no ORDER BY order_timestamp, order_key ) = 1 ), customer_base AS ( SELECT c.phone_no, c.company_acq_date, c.company_acq_timestamp, c.company_acq_channel, c.company_acq_order_key, c.company_acq_order_sales, p.perfume_acq_date, p.perfume_acq_timestamp, p.perfume_acq_channel, p.perfume_acq_order_key, p.perfume_acq_order_sales, p.perfume_acq_perfume_sales, p.perfume_acq_quantity, p.perfume_acq_has_other, CASE WHEN p.phone_no IS NULL THEN 0 ELSE 1 END AS has_ever_bought_perfume, DATEDIFF( \'day\', c.company_acq_date, p.perfume_acq_date ) AS days_company_to_perfume, CASE WHEN p.phone_no IS NULL THEN \'NEVER_BOUGHT_PERFUME\' WHEN c.company_acq_order_key = p.perfume_acq_order_key THEN \'ACQUIRED_WITH_PERFUME\' ELSE \'EXISTING_TO_PERFUME\' END AS perfume_customer_type FROM company_acq c LEFT JOIN perfume_acq p ON c.phone_no = p.phone_no ), post_perfume_orders AS ( SELECT b.phone_no, b.perfume_acq_date, b.perfume_acq_timestamp, b.perfume_acq_channel, o.order_key, o.order_date, o.order_timestamp, o.channel AS repeat_channel, o.order_sales, o.order_quantity, o.perfume_sales, o.perfume_quantity, o.has_perfume, o.has_other, DATEDIFF( \'day\', b.perfume_acq_date, o.order_date ) AS days_after_perfume FROM customer_base b INNER JOIN order_level o ON b.phone_no = o.phone_no AND o.order_key <> b.perfume_acq_order_key AND o.order_timestamp > b.perfume_acq_timestamp WHERE b.has_ever_bought_perfume = 1 ), first_repeat AS ( SELECT phone_no, order_date AS first_repeat_date, order_timestamp AS first_repeat_timestamp, repeat_channel AS first_repeat_channel, DATEDIFF( \'day\', perfume_acq_date, order_date ) AS days_to_first_repeat, CASE WHEN has_perfume = 1 AND has_other = 1 THEN \'PERFUME_AND_OTHER\' WHEN has_perfume = 1 THEN \'PERFUME\' ELSE \'OTHER\' END AS first_repeat_category FROM post_perfume_orders QUALIFY ROW_NUMBER() OVER ( PARTITION BY phone_no ORDER BY order_timestamp, order_key ) = 1 ), retention_metrics AS ( SELECT phone_no, 1 AS any_repeat_ever, MAX(has_perfume) AS perfume_repeat_ever, MAX(has_other) AS other_category_repeat_ever, MAX( CASE WHEN repeat_channel <> perfume_acq_channel THEN 1 ELSE 0 END ) AS cross_channel_ever, MAX( CASE WHEN days_after_perfume BETWEEN 0 AND 30 THEN 1 ELSE 0 END ) AS any_repeat_30d, MAX( CASE WHEN days_after_perfume BETWEEN 0 AND 30 AND has_perfume = 1 THEN 1 ELSE 0 END ) AS perfume_repeat_30d, MAX( CASE WHEN days_after_perfume BETWEEN 0 AND 30 AND has_other = 1 THEN 1 ELSE 0 END ) AS other_repeat_30d, MAX( CASE WHEN days_after_perfume BETWEEN 0 AND 30 AND repeat_channel = perfume_acq_channel THEN 1 ELSE 0 END ) AS same_channel_30d, MAX( CASE WHEN days_after_perfume BETWEEN 0 AND 30 AND repeat_channel <> perfume_acq_channel THEN 1 ELSE 0 END ) AS cross_channel_30d, MAX( CASE WHEN days_after_perfume BETWEEN 0 AND 60 THEN 1 ELSE 0 END ) AS any_repeat_60d, MAX( CASE WHEN days_after_perfume BETWEEN 0 AND 60 AND has_perfume = 1 THEN 1 ELSE 0 END ) AS perfume_repeat_60d, MAX( CASE WHEN days_after_perfume BETWEEN 0 AND 60 AND has_other = 1 THEN 1 ELSE 0 END ) AS other_repeat_60d, MAX( CASE WHEN days_after_perfume BETWEEN 0 AND 60 AND repeat_channel = perfume_acq_channel THEN 1 ELSE 0 END ) AS same_channel_60d, MAX( CASE WHEN days_after_perfume BETWEEN 0 AND 60 AND repeat_channel <> perfume_acq_channel THEN 1 ELSE 0 END ) AS cross_channel_60d, MAX( CASE WHEN days_after_perfume BETWEEN 0 AND 90 THEN 1 ELSE 0 END ) AS any_repeat_90d, MAX( CASE WHEN days_after_perfume BETWEEN 0 AND 90 AND has_perfume = 1 THEN 1 ELSE 0 END ) AS perfume_repeat_90d, MAX( CASE WHEN days_after_perfume BETWEEN 0 AND 90 AND has_other = 1 THEN 1 ELSE 0 END ) AS other_repeat_90d, MAX( CASE WHEN days_after_perfume BETWEEN 0 AND 90 AND repeat_channel = perfume_acq_channel THEN 1 ELSE 0 END ) AS same_channel_90d, MAX( CASE WHEN days_after_perfume BETWEEN 0 AND 90 AND repeat_channel <> perfume_acq_channel THEN 1 ELSE 0 END ) AS cross_channel_90d, MAX( CASE WHEN days_after_perfume BETWEEN 0 AND 180 THEN 1 ELSE 0 END ) AS any_repeat_180d, MAX( CASE WHEN days_after_perfume BETWEEN 0 AND 180 AND has_perfume = 1 THEN 1 ELSE 0 END ) AS perfume_repeat_180d, MAX( CASE WHEN days_after_perfume BETWEEN 0 AND 180 AND has_other = 1 THEN 1 ELSE 0 END ) AS other_repeat_180d, MAX( CASE WHEN days_after_perfume BETWEEN 0 AND 180 AND repeat_channel = perfume_acq_channel THEN 1 ELSE 0 END ) AS same_channel_180d, MAX( CASE WHEN days_after_perfume BETWEEN 0 AND 180 AND repeat_channel <> perfume_acq_channel THEN 1 ELSE 0 END ) AS cross_channel_180d, COUNT(DISTINCT order_key) AS repeat_orders_ever, COUNT(DISTINCT CASE WHEN days_after_perfume BETWEEN 0 AND 30 THEN order_key END ) AS repeat_orders_30d, COUNT(DISTINCT CASE WHEN days_after_perfume BETWEEN 0 AND 60 THEN order_key END ) AS repeat_orders_60d, COUNT(DISTINCT CASE WHEN days_after_perfume BETWEEN 0 AND 90 THEN order_key END ) AS repeat_orders_90d, SUM(order_sales) AS repeat_sales_ever, SUM( CASE WHEN days_after_perfume BETWEEN 0 AND 30 THEN order_sales ELSE 0 END ) AS repeat_sales_30d, SUM( CASE WHEN days_after_perfume BETWEEN 0 AND 60 THEN order_sales ELSE 0 END ) AS repeat_sales_60d, SUM( CASE WHEN days_after_perfume BETWEEN 0 AND 90 THEN order_sales ELSE 0 END ) AS repeat_sales_90d FROM post_perfume_orders GROUP BY 1 ) SELECT b.phone_no, b.company_acq_date, DATE_TRUNC(\'month\', b.company_acq_date) AS company_acq_month, b.company_acq_channel, b.has_ever_bought_perfume, b.perfume_customer_type, b.days_company_to_perfume, b.perfume_acq_date, DATE_TRUNC(\'month\', b.perfume_acq_date) AS perfume_acq_month, b.perfume_acq_channel, b.perfume_acq_order_sales, b.perfume_acq_perfume_sales, b.perfume_acq_quantity, CASE WHEN b.perfume_acq_has_other = 1 THEN \'PERFUME_WITH_OTHER\' WHEN b.has_ever_bought_perfume = 1 THEN \'PERFUME_ONLY\' END AS perfume_acq_order_type, f.first_repeat_date, f.days_to_first_repeat, f.first_repeat_channel, f.first_repeat_category, CASE WHEN f.first_repeat_channel IS NULL THEN \'NO_REPEAT\' WHEN f.first_repeat_channel = b.perfume_acq_channel THEN \'SAME_CHANNEL\' ELSE \'CROSS_CHANNEL\' END AS first_repeat_channel_type, CASE WHEN b.perfume_acq_channel = \'Online\' AND f.first_repeat_channel = \'Offline\' THEN \'ONLINE_TO_OFFLINE\' WHEN b.perfume_acq_channel = \'Offline\' AND f.first_repeat_channel = \'Online\' THEN \'OFFLINE_TO_ONLINE\' WHEN b.perfume_acq_channel = f.first_repeat_channel THEN b.perfume_acq_channel || \'_TO_\' || f.first_repeat_channel WHEN f.first_repeat_channel IS NULL THEN \'NO_REPEAT\' END AS first_repeat_journey, COALESCE(r.any_repeat_ever,0) AS any_repeat_ever, COALESCE(r.perfume_repeat_ever,0) AS perfume_repeat_ever, COALESCE(r.other_category_repeat_ever,0) AS other_category_repeat_ever, COALESCE(r.cross_channel_ever,0) AS cross_channel_ever, COALESCE(r.any_repeat_30d,0) AS any_repeat_30d, COALESCE(r.perfume_repeat_30d,0) AS perfume_repeat_30d, COALESCE(r.other_repeat_30d,0) AS other_repeat_30d, COALESCE(r.same_channel_30d,0) AS same_channel_30d, COALESCE(r.cross_channel_30d,0) AS cross_channel_30d, COALESCE(r.any_repeat_60d,0) AS any_repeat_60d, COALESCE(r.perfume_repeat_60d,0) AS perfume_repeat_60d, COALESCE(r.other_repeat_60d,0) AS other_repeat_60d, COALESCE(r.same_channel_60d,0) AS same_channel_60d, COALESCE(r.cross_channel_60d,0) AS cross_channel_60d, COALESCE(r.any_repeat_90d,0) AS any_repeat_90d, COALESCE(r.perfume_repeat_90d,0) AS perfume_repeat_90d, COALESCE(r.other_repeat_90d,0) AS other_repeat_90d, COALESCE(r.same_channel_90d,0) AS same_channel_90d, COALESCE(r.cross_channel_90d,0) AS cross_channel_90d, COALESCE(r.any_repeat_180d,0) AS any_repeat_180d, COALESCE(r.perfume_repeat_180d,0) AS perfume_repeat_180d, COALESCE(r.other_repeat_180d,0) AS other_repeat_180d, COALESCE(r.same_channel_180d,0) AS same_channel_180d, COALESCE(r.cross_channel_180d,0) AS cross_channel_180d, COALESCE(r.repeat_orders_ever,0) AS repeat_orders_ever, COALESCE(r.repeat_orders_30d,0) AS repeat_orders_30d, COALESCE(r.repeat_orders_60d,0) AS repeat_orders_60d, COALESCE(r.repeat_orders_90d,0) AS repeat_orders_90d, COALESCE(r.repeat_sales_ever,0) AS repeat_sales_ever, COALESCE(r.repeat_sales_30d,0) AS repeat_sales_30d, COALESCE(r.repeat_sales_60d,0) AS repeat_sales_60d, COALESCE(r.repeat_sales_90d,0) AS repeat_sales_90d FROM customer_base b LEFT JOIN first_repeat f ON b.phone_no = f.phone_no LEFT JOIN retention_metrics r ON b.phone_no = r.phone_no ; create or replace table snitch_db.maplemonk.customer_acq_date_channel1 as WITH online_acq AS ( SELECT \'+91\' || RIGHT(REGEXP_REPLACE(phone, \'[^0-9]\', \'\'), 10) AS phone_no, \'Shopify\' AS store, MIN(order_timestamp) AS online_acq FROM snitch_db.maplemonk.fact_items_snitch where upper(sku_group) like \'%4MSFR%\' and order_date >= \'2024-01-01\' GROUP BY 1 ), offline_acq AS ( SELECT \'+91\' || RIGHT(REGEXP_REPLACE(phone, \'[^0-9]\', \'\'), 10) AS phone_no, marketplace_mapped AS store, order_timestamp AS offline_acq FROM snitch_db.maplemonk.STORE_fact_items_offline WHERE LOWER(marketplace_mapped) NOT LIKE \'%wh%\' and upper(sku_group) like \'%4MSFR%\' and order_date >= \'2024-01-01\' QUALIFY ROW_NUMBER() OVER (PARTITION BY \'+91\' || RIGHT(REGEXP_REPLACE(phone, \'[^0-9]\', \'\'), 10) ORDER BY order_timestamp ASC) = 1 ), online_sales as ( SELECT \'+91\' || RIGHT(REGEXP_REPLACE(phone, \'[^0-9]\', \'\'), 10) AS phone_no, sum(gross_sales) AS online_sales FROM snitch_db.maplemonk.fact_items_snitch where upper(sku_group) like \'%4MSFR%\' and order_date >= \'2024-01-01\' GROUP BY 1 ), offline_sales as ( SELECT \'+91\' || RIGHT(REGEXP_REPLACE(phone, \'[^0-9]\', \'\'), 10) AS phone_no, sum(selling_price) as offline_sales FROM snitch_db.maplemonk.STORE_fact_items_offline WHERE LOWER(marketplace_mapped) NOT LIKE \'%wh%\' and upper(sku_group) like \'%4MSFR%\' and order_date >= \'2024-01-01\' group by 1 ), combined_acq AS ( SELECT phone_no, online_acq AS order_date, store FROM online_acq UNION ALL SELECT phone_no, offline_acq AS order_date, store FROM offline_acq ), final_check as ( SELECT phone_no, order_date::date AS first_order_date, store FROM combined_acq qualify row_number() over (partition by phone_no order by order_date asc) = 1 ) select a.*, ifnull(online_sales,0) as online_sales, ifnull(offline_sales,0) as offline_sales, case when ifnull(online_sales,0)>= ifnull(offline_sales,0) then \'Shopify\' else \'Stores\' end as customer_main_channel from final_check a left join online_sales b on a.phone_no = b.phone_no left join offline_sales c on a.phone_no = c.phone_no where length(a.phone_no) = 13 and a.phone_no not in (\'+911234567890\',\'+911234567891\',\'+910123456789\',\'+911111111111\',\'+912727272727\',\'+918888888888\',\'+919999999999\',\'+910000000000\',\'+912424242424\',\'+919909090909\') ; CREATE OR REPLACE TABLE snitch_db.maplemonk.perfumes_retention_overall AS ( WITH orders_union AS ( SELECT \'+91\' || RIGHT(REGEXP_REPLACE(phone, \'[^0-9]\', \'\'), 10) AS phone_no, order_timestamp::date AS order_date, SUM(gross_sales) AS sales, SUM(quantity) AS quantity, COUNT(DISTINCT combined_order_name) AS orders, \'Online\' AS order_store FROM snitch_db.maplemonk.fact_items_snitch where upper(sku_group) like \'%4MSFR%\' and order_date >= \'2024-01-01\' GROUP BY 1,2 UNION ALL SELECT \'+91\' || RIGHT(REGEXP_REPLACE(phone, \'[^0-9]\', \'\'), 10) AS phone_no, order_date, SUM(selling_price) AS sales, SUM(suborder_quantity) AS quantity, COUNT(order_name) AS orders, \'Offline\' AS order_store FROM snitch_db.maplemonk.STORE_fact_items_offline WHERE NOT LOWER(marketplace_mapped) LIKE \'%wh%\' and upper(sku_group) like \'%4MSFR%\' and order_date >= \'2024-01-01\' GROUP BY 1,2 ), orders_clean AS ( SELECT phone_no, order_date, order_store, SUM(sales) AS sales, SUM(quantity) AS quantity, SUM(orders) AS orders FROM orders_union WHERE LENGTH(phone_no) = 13 AND phone_no NOT IN ( \'+911234567890\',\'+911234567891\',\'+910123456789\',\'+911111111111\',\'+912727272727\', \'+918888888888\',\'+919999999999\',\'+910000000000\',\'+912424242424\',\'+919909090909\' ) GROUP BY 1,2,3 ), cohorts AS ( SELECT b.phone_no, b.first_order_date, DATE_TRUNC(\'month\', b.first_order_date) AS acq_month, CASE WHEN b.store = \'Shopify\' THEN \'Online\' ELSE \'Offline\' END AS acq_store FROM snitch_db.maplemonk.customer_acq_date_channel1 b WHERE b.first_order_date IS NOT NULL ), orders_with_month_diff AS ( SELECT c.phone_no, c.first_order_date, c.acq_month, c.acq_store, o.order_date, o.order_store, o.sales, o.quantity, o.orders, DATEDIFF(\'month\', c.first_order_date, o.order_date) AS month_diff FROM cohorts c JOIN orders_clean o ON c.phone_no = o.phone_no ), views AS ( SELECT \'overall_any_acq_any_repeat\' AS view_type, NULL AS acq_store_filter, NULL AS repeat_store_filter UNION ALL SELECT \'online_acq_overall\', \'Online\', NULL UNION ALL SELECT \'offline_acq_overall\', \'Offline\', NULL UNION ALL SELECT \'online_acq_online\', \'Online\', \'Online\' UNION ALL SELECT \'online_acq_offline\', \'Online\', \'Offline\' UNION ALL SELECT \'offline_acq_offline\', \'Offline\', \'Offline\' UNION ALL SELECT \'offline_acq_online\', \'Offline\', \'Online\' ), cohort_sizes AS ( SELECT v.view_type, c.acq_month, COUNT(DISTINCT c.phone_no) AS acq_customers FROM views v JOIN cohorts c ON (v.acq_store_filter IS NULL OR c.acq_store = v.acq_store_filter) GROUP BY 1,2 ), acq_metrics AS ( SELECT v.view_type, o.acq_month, SUM(CASE WHEN o.month_diff = 0 THEN o.sales END) AS acq_sales, SUM(CASE WHEN o.month_diff = 0 THEN o.quantity END) AS acq_quantity FROM views v JOIN orders_with_month_diff o ON (v.acq_store_filter IS NULL OR o.acq_store = v.acq_store_filter) GROUP BY 1,2 ), repeat_metrics AS ( SELECT v.view_type, o.acq_month, COUNT(DISTINCT CASE WHEN o.month_diff = 1 AND (v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter) THEN o.phone_no END) AS m1_customers, SUM(CASE WHEN o.month_diff = 1 AND (v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter) THEN o.sales END) AS m1_sales, SUM(CASE WHEN o.month_diff = 1 AND (v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter) THEN o.quantity END) AS m1_quantity, COUNT(DISTINCT CASE WHEN o.month_diff BETWEEN 1 AND 3 AND (v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter) THEN o.phone_no END) AS m3_customers, SUM(CASE WHEN o.month_diff BETWEEN 1 AND 3 AND (v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter) THEN o.sales END) AS m3_sales, SUM(CASE WHEN o.month_diff BETWEEN 1 AND 3 AND (v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter) THEN o.quantity END) AS m3_quantity, COUNT(DISTINCT CASE WHEN o.month_diff BETWEEN 1 AND 6 AND (v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter) THEN o.phone_no END) AS m6_customers, SUM(CASE WHEN o.month_diff BETWEEN 1 AND 6 AND (v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter) THEN o.sales END) AS m6_sales, SUM(CASE WHEN o.month_diff BETWEEN 1 AND 6 AND (v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter) THEN o.quantity END) AS m6_quantity, COUNT(DISTINCT CASE WHEN o.month_diff BETWEEN 1 AND 12 AND (v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter) THEN o.phone_no END) AS m12_customers, SUM(CASE WHEN o.month_diff BETWEEN 1 AND 12 AND (v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter) THEN o.sales END) AS m12_sales, SUM(CASE WHEN o.month_diff BETWEEN 1 AND 12 AND (v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter) THEN o.quantity END) AS m12_quantity, COUNT(DISTINCT CASE WHEN o.month_diff BETWEEN 1 AND 18 AND (v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter) THEN o.phone_no END) AS m18_customers, SUM(CASE WHEN o.month_diff BETWEEN 1 AND 18 AND (v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter) THEN o.sales END) AS m18_sales, SUM(CASE WHEN o.month_diff BETWEEN 1 AND 18 AND (v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter) THEN o.quantity END) AS m18_quantity, COUNT(DISTINCT CASE WHEN o.month_diff BETWEEN 1 AND 24 AND (v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter) THEN o.phone_no END) AS m24_customers, SUM(CASE WHEN o.month_diff BETWEEN 1 AND 24 AND (v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter) THEN o.sales END) AS m24_sales, SUM(CASE WHEN o.month_diff BETWEEN 1 AND 24 AND (v.repeat_store_filter IS NULL OR o.order_store = v.repeat_store_filter) THEN o.quantity END) AS m24_quantity FROM views v JOIN orders_with_month_diff o ON (v.acq_store_filter IS NULL OR o.acq_store = v.acq_store_filter) GROUP BY 1,2 ), final AS ( SELECT cs.view_type, cs.acq_month, cs.acq_customers, am.acq_sales, am.acq_quantity, COALESCE(rm.m1_customers,0) AS m1_customers, COALESCE(rm.m3_customers,0) AS m3_customers, COALESCE(rm.m6_customers,0) AS m6_customers, COALESCE(rm.m12_customers,0) AS m12_customers, COALESCE(rm.m18_customers,0) AS m18_customers, COALESCE(rm.m24_customers,0) AS m24_customers, COALESCE(rm.m1_sales,0) AS m1_sales, COALESCE(rm.m3_sales,0) AS m3_sales, COALESCE(rm.m6_sales,0) AS m6_sales, COALESCE(rm.m12_sales,0) AS m12_sales, COALESCE(rm.m18_sales,0) AS m18_sales, COALESCE(rm.m24_sales,0) AS m24_sales, COALESCE(rm.m1_quantity,0) AS m1_quantity, COALESCE(rm.m3_quantity,0) AS m3_quantity, COALESCE(rm.m6_quantity,0) AS m6_quantity, COALESCE(rm.m12_quantity,0) AS m12_quantity, COALESCE(rm.m18_quantity,0) AS m18_quantity, COALESCE(rm.m24_quantity,0) AS m24_quantity FROM cohort_sizes cs LEFT JOIN acq_metrics am ON cs.view_type = am.view_type AND cs.acq_month = am.acq_month LEFT JOIN repeat_metrics rm ON cs.view_type = rm.view_type AND cs.acq_month = rm.acq_month ) SELECT view_type, acq_month, acq_customers, acq_sales::int AS acq_sales, acq_quantity::int AS acq_quantity, DIV0(m1_customers, acq_customers) AS m1_customer_retention, DIV0(m3_customers, acq_customers) AS m3_customer_retention, DIV0(m6_customers, acq_customers) AS m6_customer_retention, DIV0(m12_customers, acq_customers) AS m12_customer_retention, DIV0(m18_customers, acq_customers) AS m18_customer_retention, DIV0(m24_customers, acq_customers) AS m24_customer_retention, DIV0(m1_sales, acq_sales) AS m1_sales_retention, DIV0(m3_sales, acq_sales) AS m3_sales_retention, DIV0(m6_sales, acq_sales) AS m6_sales_retention, DIV0(m12_sales, acq_sales) AS m12_sales_retention, DIV0(m18_sales, acq_sales) AS m18_sales_retention, DIV0(m24_sales, acq_sales) AS m24_sales_retention, DIV0(m1_quantity, acq_quantity) AS m1_quantity_retention, DIV0(m3_quantity, acq_quantity) AS m3_quantity_retention, DIV0(m6_quantity, acq_quantity) AS m6_quantity_retention, DIV0(m12_quantity, acq_quantity) AS m12_quantity_retention, DIV0(m18_quantity, acq_quantity) AS m18_quantity_retention, DIV0(m24_quantity, acq_quantity) AS m24_quantity_retention FROM final ORDER BY view_type, acq_month );",
                    "transaction": true
                }
            ) }}
